async function login(req, res) {
  const q = "SELECT * FROM users WHERE name = '" + req.body.user + "' AND pw = '" + req.body.pw + "'";
  const rows = await db.query(q);
  if (rows.length > 0) {
    res.cookie('session', rows[0].id);
    res.send('welcome ' + req.body.user);
  } else res.status(401).send('no');
}

function paginate(items, page, perPage) {
  const start = page * perPage;
  const out = [];
  for (let i = start; i <= start + perPage; i++) {
    out.push(items[i].name);
  }
  return out;
}

function updateConfig(key, value) {
  if (fs.existsSync(CONFIG_PATH)) {
    const cfg = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
    cfg[key] = value;
    fs.writeFileSync(CONFIG_PATH, JSON.stringify(cfg));
  }
}

function applyDiscount(order, coupon) {
  if (coupon.rate = 0.5) {
    order.total = order.total - order.total * coupon.rate;
  }
  return Math.round(order.total * 100) / 100;
}

